import{_ as d,a0 as r,w as i,s,ao as a,I as e,x as o,a1 as t,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"在linux中如何通過nload來監控網絡使用情況 | LCTT x X-CMD","titleTemplate":false,"description":"在linux中如何通過nload來監控網絡使用情況 | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在linux中如何通過nload來監控網絡使用情況 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在linux中如何通過nload來監控網絡使用情況 | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20150121 How to Monitor Network Usage with nload in Linux","title":"在linux中如何通過nload來監控網絡使用情況","tag":"201503","desc":""},"relativePath":"201503/20150121 How to Monitor Network Usage with nload in Linux.md","filePath":"[post].md"}'),g={name:"201503/20150121 How to Monitor Network Usage with nload in Linux.md"};function u(m,n,x,c,h,w){const l=r("Link");return i(),s("div",null,[n[16]||(n[16]=a(`<h1 id="在linux中如何通過nload來監控網絡使用情況" tabindex="-1">在linux中如何通過nload來監控網絡使用情況 <a class="header-anchor" href="#在linux中如何通過nload來監控網絡使用情況" aria-label="Permalink to “在linux中如何通過nload來監控網絡使用情況”">​</a></h1><p>nload 是一個 linux 自由軟件工具，通過提供兩個簡單的圖形來幫助linux用户和系統管理員來實時監控網絡流量以及寬帶使用情況：一個是進入流量，一個是流出流量。</p><p>我真的很喜歡用<strong>nload</strong>來在屏幕上顯示當前的下載速度、總的流入量和平均下載速度等信息。nload工具的報告圖非常容易理解，最重要的是這些信息真的非常有用。</p><p>在其使用手冊上説到，在默認情況下它會監控所有網絡設備。但是你可以輕鬆地指定你想要監控的設備，而且可以通過方向鍵在不同的網絡設備之間進行轉換。另外還有很多的選項可用，例如 ‘-t’選項以毫秒來設定刷新顯示時間間隔（默認時間間隔值是500毫秒），‘-m’選項用來同時顯示多個設備（在使用該選項時不會顯示流量圖），‘-u’選項用來設置顯示流量數字的單位，另外還有許多其他的選項將會在本教程中探索和練習。</p><h3 id="如何將-nload安裝到你的linux機器上" tabindex="-1">如何將 nload安裝到你的linux機器上 <a class="header-anchor" href="#如何將-nload安裝到你的linux機器上" aria-label="Permalink to “如何將 nload安裝到你的linux機器上”">​</a></h3><p><strong>Ubuntu</strong> 和 <strong>Fedora</strong> 用户可以從默認的軟件倉庫中容易地安裝。</p><p>在Ubuntu上使用以下命令進行安裝。</p><pre><code>sudo apt-get install nload
</code></pre><p>在Fedora上使用以下命令進行安裝。</p><pre><code>sudo yum install nload
</code></pre><p><strong>CentOS</strong>用户該怎麼辦呢？ 只需要在你的機器上輸入以下命令就可以安裝成功。</p><pre><code>sudo yum install nload
</code></pre><p>以下的命令會幫助你在OpenBSD系統中安裝nload。</p><pre><code>sudo pkg_add -i nload
</code></pre><p>在 linux 機器上的另外一個非常有效的安裝軟件的方式就是編譯源代碼，下載並安裝最新的版本意味着能夠獲得更好地性能、更酷的特性以及更少的bug。</p><h3 id="如何通過源代碼安裝nload" tabindex="-1">如何通過源代碼安裝nload <a class="header-anchor" href="#如何通過源代碼安裝nload" aria-label="Permalink to “如何通過源代碼安裝nload”">​</a></h3><p>在從源代碼安裝nload之前，你需要首先下載源代碼。 我通常使用wget工具來進行下載--該工具在許多linux機器上默認可用。該免費工具幫助用户以非交互式的方式從網絡上下載文件，並支持以下協議：</p><ul><li>HTTP</li><li>HTTPS</li><li>FTP</li></ul><p>通過以下命令來進入到<strong>/tmp</strong>目錄中。</p><pre><code>cd /tmp
</code></pre><p>然後在你的終端中輸入以下命令就可以將最新版本的nload下載到你的linux機器上了。</p><pre><code>wget http://www.roland-riegel.de/nload/nload-0.7.4.tar.gz
</code></pre>`,22)),e("p",null,[n[1]||(n[1]=o("如果你不喜歡使用wget工具，也可以通過簡單的一個鼠標點擊輕鬆地從",-1)),t(l,{href:"http://www.roland-riegel.de/nload/nload-0.7.4.tar.gz"},{default:p(()=>[...n[0]||(n[0]=[o("官網",-1)])]),_:1}),n[2]||(n[2]=o("上下載其源代碼。",-1))]),n[17]||(n[17]=a(`<p>由於該軟件非常輕巧，其下載過程幾乎在瞬間就會完成。接下來的步驟就是通過<strong>tar</strong>工具來將下載的源代碼包進行解壓。</p><p>tar歸檔工具可以用來從磁帶或硬盤文檔中存儲或解壓文件，該工具有許多可用的選項，但是我們只需要下面的幾個選項來執行我們的操作。</p><ol><li><strong>-x</strong> 從歸檔中解壓文件</li><li><strong>-v</strong> 使用繁瑣模式運行--用來顯示詳細信息</li><li><strong>-f</strong> 用來指定歸檔文件</li></ol><p>例如（LCTT 譯註：tar 命令的參數前的“-”可以省略）：</p><pre><code>tar xvf example.tar
</code></pre><p>現在你學會了如何使用tar工具，我可以非常肯定你知道了如何從命令列中解壓這個.tar文檔。</p><pre><code>tar xvf nload-0.7.4.tar.gz
</code></pre><p>之後使用cd命令來進入到nload*目錄中：</p><pre><code>cd nload*
</code></pre><p>在我的系統上看起來是這樣的：</p><pre><code>oltjano@baby:/tmp/nload-0.7.4$
</code></pre><p>然後運行下面這個命令來為你的系統配置該軟件包：</p><pre><code>./configure
</code></pre><p>此時會有“一大波殭屍”會在你的屏幕上顯示出來，下面的一個屏幕截圖描述了它的樣子。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nload1.png" alt="configuring packages for nload"></p><p>在上述命令完成之後，通過下面的命令來編譯nload。</p><pre><code>make
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nload2.png" alt="compiling nload"></p><p>好了，終於....，通過以下命令可以將nload安裝在你的機器上了。</p><pre><code>sudo make install
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nload3.png" alt="installing nload from source"></p><p>安裝好nload之後就是讓你學習如何使用它的時間了。</p><p>###如何使用nload###</p><p>我喜歡探索，所以在你的終端輸入以下命令.</p><pre><code>nload
</code></pre><p>看到了什麼？</p><p>我得到了下面的結果。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nload4.png" alt="running nload"></p><p>如上述截圖可以看到,我得到了以下信息:</p><h4 id="流入量" tabindex="-1">流入量#### <a class="header-anchor" href="#流入量" aria-label="Permalink to “流入量####”">​</a></h4><p><strong>當前下載速度</strong></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nload4.1.png" alt="nload running on linux"></p><p><strong>平均下載速度</strong></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nload4.2.png" alt="nload running on linux"></p><p><strong>最小下載速度</strong></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nload4.3.png" alt="nload running on linux"></p><p><strong>最大下載速度</strong></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nload4.4.png" alt="nload running on linux"></p><p><strong>總的流入量按字節進行顯示</strong></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nload4.5.png" alt=""></p><h4 id="流出量" tabindex="-1">流出量 <a class="header-anchor" href="#流出量" aria-label="Permalink to “流出量”">​</a></h4><p>類似的同樣適用於流出量</p><h4 id="一些nload有用的選項" tabindex="-1">一些nload有用的選項#### <a class="header-anchor" href="#一些nload有用的選項" aria-label="Permalink to “一些nload有用的選項####”">​</a></h4><p>使用選項</p><pre><code>   -u
</code></pre><p>用來設置顯示流量單位。</p><p>下面的命令會幫助你使用MBit/s顯示單元</p><pre><code>nload -u m
</code></pre><p>下面的屏幕截圖顯示了上述命令的結果。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nload5.png" alt="nload running on linux"></p><p>嘗試以下命令然後看看有什麼結果。</p><pre><code>nload -u g
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nload6.png" alt="nload running on linux"></p><p>同時還有一個<strong>-U</strong>選項。根據手冊描述，該選項基本上與-u選項類似，只是用在合計數據。 我測試了這個命令，老實説，當你需要檢查總的流入與流出量時非常有用。</p><pre><code>nload -U G
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nload7.png" alt="nload running on linux"></p><p>從上面的截圖中可以看到，<strong>nload -U G</strong> 使用Gbyte來顯示數據總量。</p><p>另外一個我喜歡使用的有用選項是 <strong>-t</strong>。 該選項用來設置刷新顯示事件間隔，單位為毫秒，默認值為500毫秒。</p><p>我會通過下面的命令做一些小的實驗。</p><pre><code>nload -t 130
</code></pre><p>那麼上述命令做了什麼呢？它將刷新顯示時間間隔設置為130毫秒。 通常推薦不要將該時間間隔值設置為小於100毫秒，因為nload在生成報告時計算錯誤。</p><p>另外的一個選項為 <strong>-a</strong>， 在你想要設置計算平均值的時間窗口的秒數時使用，默認該值為300秒。</p><p>那麼當你想要監控指定的網絡設備該如何呢？ 非常容易， 像下面這樣簡單地指定設備或者列出想要監控的設備列表即可。</p><pre><code>nload wlan0
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nload8.png" alt="nload monitoring wlan0 on linux"></p><p>下面的語法可幫助你監控指定的多個設備。</p><pre><code>nload [options] device1 device2 devicen
</code></pre><p>例如，使用下面的命令來監控eth0和eth1。</p><pre><code>nload wlan0 eth0
</code></pre><p>如果不帶選項來運行nload，那麼它會監控所有自動檢測到的設備，你可以通過左右方向鍵來顯示其中的任何一個設備的信息。</p><hr>`,71)),e("p",null,[n[4]||(n[4]=o("via: ",-1)),t(l,{href:"http://linoxide.com/monitoring-2/monitor-network-usage-nload/"},{default:p(()=>[...n[3]||(n[3]=[o("http://linoxide.com/monitoring-2/monitor-network-usage-nload/",-1)])]),_:1})]),e("p",null,[n[8]||(n[8]=o("作者：",-1)),t(l,{href:"http://linoxide.com/author/oltjano/"},{default:p(()=>[...n[5]||(n[5]=[o("Oltjano Terpollari",-1)])]),_:1}),n[9]||(n[9]=o(" 譯者：",-1)),t(l,{href:"https://github.com/theo-l"},{default:p(()=>[...n[6]||(n[6]=[o("theo-l",-1)])]),_:1}),n[10]||(n[10]=o(" 校對：",-1)),t(l,{href:"https://github.com/wxy"},{default:p(()=>[...n[7]||(n[7]=[o("wxy",-1)])]),_:1})]),e("p",null,[n[13]||(n[13]=o("本文由 ",-1)),t(l,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...n[11]||(n[11]=[o("LCTT",-1)])]),_:1}),n[14]||(n[14]=o(" 原創翻譯，",-1)),t(l,{href:"http://linux.cn/"},{default:p(()=>[...n[12]||(n[12]=[o("Linux中國",-1)])]),_:1}),n[15]||(n[15]=o(" 榮譽推出",-1))])])}const k=d(g,[["render",u]]);export{b as __pageData,k as default};
